import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry, pointwise_dynamic

logger = logging.getLogger(__name__)

NUM_SIPS = 24

# GCU400 override of the generic pointwise_dynamic implementation.  The generic
# path dispatches a block-pointer kernel on only 12 CTAs (generic ENFLAME
# codegen config), which costs ~7.2ms vs the ~0.9ms native floor on the 512M
# element core shape.  The flat grid-stride kernels below keep the fp32 math
# body and saturate all 48 SIPS (same structure as sigmoid.py /
# special_expit.py).  Per-dtype body choice, measured on L600 with the core
# benchmark (do_bench kernel median): fp32 computes (exp(x)-exp(-x))*0.5 with
# the native tl.exp and runs at the copy floor (512M: 1349 vs 1354us native);
# for fp16/bf16 the second tl.exp makes the kernel ALU-bound (1565us), while
# the algebraic equivalent 0.5*exp(x) - 0.5/exp(x) trades the second
# transcendental for one IEEE division and wins (512M: 1287us).  The same
# division is a large loss for fp32 (2244us) because fp32 traffic no longer
# hides it, hence the dtype split.  Extern __ef_sinhf / __ef_frcp_rn are
# software slow paths (13988 / 59947us at 512M) and are not used.


@libentry()
@triton.jit(do_not_specialize=["N_total"])
def sinh_flat_kernel(x_ptr, out_ptr, N_total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    num_blocks = (N_total + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        off = block_id * BLOCK + arange
        mask = off < N_total
        x = tl.load(x_ptr + off, mask=mask).to(tl.float32)
        out = 0.5 * (tl.exp(x) - tl.exp(-x))
        tl.store(out_ptr + off, out, mask=mask)


@libentry()
@triton.jit(do_not_specialize=["N_total"])
def sinh_rcp_flat_kernel(x_ptr, out_ptr, N_total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    num_blocks = (N_total + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        off = block_id * BLOCK + arange
        mask = off < N_total
        x = tl.load(x_ptr + off, mask=mask).to(tl.float32)
        t = tl.exp(x)
        out = 0.5 * t - 0.5 / t
        tl.store(out_ptr + off, out, mask=mask)


@pointwise_dynamic(promotion_methods=[(0, "INT_TO_FLOAT")])
@triton.jit
def sinh_kernel(x):
    # sinh(x) = (exp(x) - exp(-x)) / 2
    x_f32 = x.to(tl.float32)
    return (tl.exp(x_f32) - tl.exp(-x_f32)) * 0.5


def _choose_block(N_total, itemsize):
    # do_bench(median) sweep, kernel mode, vs torch.sinh on GCU400: tiny
    # shapes want the exact next_pow2 tile; 16.7M peaks at 65536 (fp16
    # 51.2 vs 52.4us @32768); the 512M bucket splits by dtype -- 2-byte
    # elements gain ~3% from 131072 (1287 vs 1325us @65536) while fp32 is
    # fastest at 65536 (1349 vs 1386us @32768).
    if N_total <= 8192:
        return triton.next_power_of_2(N_total)
    if N_total <= 65536:
        return 8192
    if N_total <= 524288:
        return 32768
    if N_total > (1 << 28) and itemsize <= 2:
        return 131072
    return 65536


def _launch_sinh_flat(inp, out, N_total, itemsize, dtype):
    BLOCK = _choose_block(N_total, itemsize)
    grid_size = min(triton.cdiv(N_total, BLOCK), NUM_SIPS * 2)
    if dtype == torch.float32:
        kernel, num_warps = sinh_flat_kernel, 4
    else:
        kernel, num_warps = sinh_rcp_flat_kernel, 2
    # The external llvm converter intermittently fails on cold compiles
    # (nondeterministic; observed as converterResult=-2 and a misresolved
    # converter helper script during a host-level userland flake window);
    # retrying the launch recompiles and succeeds.  3 attempts keep
    # deterministic breakage loud while riding out the flake (atan2_.py
    # precedent for the same toolchain family).
    for attempt in range(3):
        try:
            with torch_device_fn.device(inp.device):
                kernel[(grid_size,)](
                    inp, out, N_total, BLOCK=BLOCK, num_warps=num_warps
                )
            return out
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "sinh flat kernel launch failed (attempt %d): %s", attempt + 1, exc
            )


def sinh(A):
    logger.debug("GEMS_ENFLAME SINH")
    if A.dtype not in (torch.float16, torch.bfloat16, torch.float32):
        return sinh_kernel(A)
    inp = A if A.is_contiguous() else A.contiguous()
    out = torch.empty_like(inp)
    N_total = inp.numel()
    if N_total == 0:
        return out

    _launch_sinh_flat(inp, out, N_total, inp.element_size(), inp.dtype)
    return out


def sinh_(A):
    logger.debug("GEMS_ENFLAME SINH_")
    if A.dtype not in (torch.float16, torch.bfloat16, torch.float32):
        sinh_kernel(A, out0=A)
        return A
    if not A.is_contiguous():
        A.copy_(sinh(A))
        return A
    N_total = A.numel()
    if N_total == 0:
        return A

    _launch_sinh_flat(A, A, N_total, A.element_size(), A.dtype)
    return A
